output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to collect the available cart from the entrance cart station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "has_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_pickup_item_without_cart",
    "text": "Customers are prohibited from picking up grocery items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Customers are prohibited from carrying items by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_item": "handFull",
        "has_cart": "hasCart"
      },
      "events": {
        "item_taken_into_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": "hand_carrying_item"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_carrying_item",
          "item_taken_into_hand"
        ]
      }
    }
  },
  {
    "id": "must_return_cart_to_nw_bay",
    "text": "Customers are obliged to return their cart to the northwest cart bay before exiting.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_bay": "at(0,1)",
        "cart_parked_at_nw_bay": "cartAt(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "return_cart_to_nw_bay": {
          "pre": {
            "and": [
              "at_nw_cart_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_nw_bay"
    }
  },
  {
    "id": "no_leaving_cart_outside_bay",
    "text": "Customers are prohibited from leaving a cart anywhere other than the northwest cart bay.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_nw_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_nw_cart_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_nw_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "has_cart"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "Customers may exit only after the cart has been parked at the northwest cart bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_nw_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_at_nw_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_bypassing_return_bay_with_cart",
    "text": "Customers who arrive at the northwest cart bay with a cart are prohibited from moving on with it instead of leaving it there.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_bay": "at(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "move_from_nw_bay_with_cart": {
          "pre": {
            "and": [
              "at_nw_cart_bay",
              "has_cart",
              "MOVE"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_from_nw_bay_with_cart"
    }
  }
]
